import{_ as o,a0 as n,w as d,s,ao as e,I as r,x as i,a1 as u,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"在 Linux 上用 Audacity 编辑音频 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上用 Audacity 编辑音频 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上用 Audacity 编辑音频 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上用 Audacity 编辑音频 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20211201 Edit audio on Linux with Audacity","title":"在 Linux 上用 Audacity 编辑音频","tag":"202201","desc":""},"relativePath":"202201/20211201 Edit audio on Linux with Audacity.md","filePath":"[post].md"}'),p={name:"202201/20211201 Edit audio on Linux with Audacity.md"};function y(b,t,m,f,g,A){const a=n("Link");return d(),s("div",null,[t[51]||(t[51]=e('<h1 id="在-linux-上用-audacity-编辑音频" tabindex="-1">在 Linux 上用 Audacity 编辑音频 <a class="header-anchor" href="#在-linux-上用-audacity-编辑音频" aria-label="Permalink to “在 Linux 上用 Audacity 编辑音频”">​</a></h1><blockquote><p>Audacity 是开源软件世界中的一个经典的强大工具，可以用于录音、编辑等对声音进行操作。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202201/09/130245b7jozrrrc7gorgae.jpg" alt=""></p><p>Audacity 声音编辑器是填补了一个似乎没有人意识到的空白的开源应用程序。它最初是在卡内基梅隆大学开发的，当时很多人还认为电脑只是用来办公和学习的，要进行严肃的多媒体工作需要特殊的 DSP 外围设备。Audacity 认识到，普通计算机用户偶尔也需要编辑音频。在此后的 20 年里，Audacity 团队一直为录音和清理声音打造这个开源的应用程序。</p><p>我经常使用 Audacity，作为一个受过培训的编辑，我已经习惯了在我的应用程序中使用重要的、通常是单键的键盘快捷键。通过围绕单个字母建立快捷键，你可以一只手放在鼠标上，一只手放在键盘上，所以选择一个工具或一个重要功能和点击鼠标之间的延迟仅仅是几毫秒而已。在本文中，我将专门给出我在 Audacity 中使用的键盘快捷方式，如果你想优化自己的设置可以参考。</p><h3 id="在-linux-上安装-audacity" tabindex="-1">在 Linux 上安装 Audacity <a class="header-anchor" href="#在-linux-上安装-audacity" aria-label="Permalink to “在 Linux 上安装 Audacity”">​</a></h3><p>在大多数 Linux 发行版上，Audacity 都可以从你的软件包管理器中获得。在 Fedora、Mageia 和类似的发行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install audacity</span></span></code></pre></div><p>在 Elementary、Mint 和其他基于 Debian 的发行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install audacity</span></span></code></pre></div>',10)),r("p",null,[t[1]||(t[1]=i("然而，我是以 ",-1)),u(a,{href:"https://opensource.com/article/21/11/how-install-flatpak-linux"},{default:l(()=>[...t[0]||(t[0]=[i("Flatpak",-1)])]),_:1}),t[2]||(t[2]=i(" 方式来使用 Audacity 的。",-1))]),r("p",null,[t[4]||(t[4]=i("在 Windows 或 macOS 上，可以从 ",-1)),u(a,{href:"https://www.audacityteam.org/"},{default:l(()=>[...t[3]||(t[3]=[i("Audacity 网站",-1)])]),_:1}),t[5]||(t[5]=i(" 下载一个 Audacity 安装程序。",-1))]),r("p",null,[t[7]||(t[7]=i("它最近有一个叫做 ",-1)),u(a,{href:"https://github.com/tenacityteam/tenacity"},{default:l(()=>[...t[6]||(t[6]=[i("Tenacity",-1)])]),_:1}),t[8]||(t[8]=i(" 的复刻版本，是另外的开发者团队准备延续 Audacity 的传统而开发的。在写这篇文章的时候，两者基本上是相同的应用程序，所以这篇文章同样适用于两者。以后是否在功能上有分歧，还有待观察。",-1))]),t[52]||(t[52]=e('<p>安装后，从你的应用程序或活动菜单中启动该应用程序。</p><h3 id="在-audacity-中设置输入" tabindex="-1">在 Audacity 中设置输入 <a class="header-anchor" href="#在-audacity-中设置输入" aria-label="Permalink to “在 Audacity 中设置输入”">​</a></h3><p>首先，你必须设置你的音频 <em>输入</em>，以便 Audacity 接收你使用的麦克风或音频接口的信号。你选择什么输入取决于你的设置和你拥有的音频外围设备。USB 麦克风通常被标为 <ruby>麦克风<rt> Microphone</rt></ruby>，但带有 1/8&quot; 输入插孔的麦克风可能被标为 <ruby>线路输入<rt>Line in</rt></ruby>。你可以选择不同输入：</p><h4 id="pulse-audio-音频服务器" tabindex="-1">Pulse Audio 音频服务器 <a class="header-anchor" href="#pulse-audio-音频服务器" aria-label="Permalink to “Pulse Audio 音频服务器”">​</a></h4><p>Linux 使用<ruby>高级 Linux 声音架构<rt>Advanced Linux Sound Architecture</rt></ruby>（ALSA）作为其声音的后端，而 macOS 和 Windows 则使用自己的封闭框架。在 Linux 上，你可以将 Pulse Audio 音频服务器设置为你的输入源，将 Audacity 导向 <em>一个</em> 虚拟接口（Pulse），因此你可以从系统设置中选择声音输入。这是我的首选方法，因为它将所有控制集中在一个方便的控制面板上。在一个应用程序中选择一个麦克风，却发现麦克风在其他地方被静音的日子已经一去不复返了。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-sound-setting.png" alt="声音输入" title="Sound input"></p><h4 id="设备访问" tabindex="-1">设备访问 <a class="header-anchor" href="#设备访问" aria-label="Permalink to “设备访问”">​</a></h4><p>如果你的发行版或操作系统没有使用 Pulse Audio 音频服务器，或者由于某种原因你喜欢直接访问声音设备，你可以从下拉菜单中选择一个设备。这需要了解你的系统是如何列出声音设备的，这有时候并不很好找。台式机可能有几个输入源，有些在机箱的后面，有些在前面的面板上。笔记本电脑通常输入方式较少，但你可能在网络摄像头附近有一个麦克风，如果你使用的是外部麦克风，可能还有一个。</p><h3 id="用-audacity-录制音频" tabindex="-1">用 Audacity 录制音频 <a class="header-anchor" href="#用-audacity-录制音频" aria-label="Permalink to “用 Audacity 录制音频”">​</a></h3><p>选中你的输入后，按“<ruby>录音<rt>Record</rt></ruby>”按钮（有红点的按钮）。</p><p><img src="https://opensource.com/sites/default/files/uploads/audacity-input.png" alt="录制音频" title="Recording audio"></p>',11)),r("p",null,[t[10]||(t[10]=i("如果你是对着麦克风录音，你所要做的就是开始说话。如果你从，比如说，",-1)),u(a,{href:"https://opensource.com/article/18/1/audacity-digitize-records"},{default:l(()=>[...t[9]||(t[9]=[i("黑胶唱片机",-1)])]),_:1}),t[11]||(t[11]=i(" 录制输入，那么你必须启动它。不管是什么，只要 Audacity 处于录音模式，任何发送到你选择的输入的信号都会被写入 Audacity 并在你的屏幕上呈现为波形。",-1))]),t[53]||(t[53]=e('<p><strong>我的快捷方式：</strong> 我使用 <code>R</code> 键来开始录音。默认情况下，按下空格键停止录音（也可以回放录音）。</p><h3 id="编辑音频" tabindex="-1">编辑音频 <a class="header-anchor" href="#编辑音频" aria-label="Permalink to “编辑音频”">​</a></h3><p>录音很少完全按计划进行。也许你过早地开始录音，不得不忍受几秒钟的黑胶静音（它就像静音，但更嘈杂），或者你发现你的语气停顿都是 “呃”、“嗯”或其他声调，或者你一开始就录制错误了。Audacity 首先是一个波形编辑器，这意味着你可以在最终的录音中剪掉你不想要的声音，就像你在文字处理器中输入的文字一样容易编辑。</p><h3 id="编辑过零点的声音" tabindex="-1">编辑过零点的声音 <a class="header-anchor" href="#编辑过零点的声音" aria-label="Permalink to “编辑过零点的声音”">​</a></h3><p>Audacity 的主要编辑工具是“<ruby>选择工具<rt>Selection Tool</rt></ruby>”。它是你在文字处理程序中看到的熟悉的“工字形”光标，它的功能在这里也是一样。你可以点击并拖动这个光标，穿过声音的一个区域，然后你可以复制、粘贴、剪切、删除或直接播放这个区域。</p><p><strong>我的快捷键：</strong> 我用 <code>I</code> 键来激活“<ruby>选择工具<rt>Selection Tool</rt></ruby>”，因为光标看起来像字母 “I”。</p>',6)),r("p",null,[t[14]||(t[14]=i("在文字处理器中，你可以非常清楚地看到每个字母的结尾和开头。你不可能不小心选择和删除一个字母的一半。然而，在现代应用程序中，声音的 “分辨率”（称为 ",-1)),t[15]||(t[15]=r("em",null,"采样率",-1)),t[16]||(t[16]=i("）非常好，所以人眼很难在音频波中找到一个清晰的断点。Audacity 可以调整你的选择，使你选择的区域落在所谓的 ",-1)),r("ruby",null,[u(a,{href:"https://en.wikipedia.org/wiki/Zero_crossing"},{default:l(()=>[...t[12]||(t[12]=[i("过零点",-1)])]),_:1}),t[13]||(t[13]=r("rt",null,"zero crossing",-1))]),t[17]||(t[17]=i("，这可以避免在你做切割的地方出现微妙但明显的突兀现象。",-1))]),t[54]||(t[54]=e('<p><img src="https://opensource.com/sites/default/files/uploads/audacity-zero-crossing.jpg" alt="过零点" title="Zero crossing"></p><p>在你做出选择后，进入“<ruby>选择<rt> Select</rt></ruby>”菜单，选择 “<ruby>在过零点<rt>At Zero Crossings</rt></ruby>”。</p><p><strong>我的快捷键：</strong> 我使用 <code>Z</code> 键来调整选区到过零点，使用 <code>X</code> 键来删除一个区域（它使我不必将手一直移到 <code>Del</code> 或 <code>Backspace</code> ）。</p><h3 id="腾出空间" tabindex="-1">腾出空间 <a class="header-anchor" href="#腾出空间" aria-label="Permalink to “腾出空间”">​</a></h3><p>编辑的好处是，你的最终产品不一定要与你录制的内容一致。我曾经录制过一些讲座，甚至录制过一些读物的剧本，但最终因为某种原因而偏离了方向，或者遗漏了一部分重要的信息，后来在发布前又重新编排或添加了全新的音频。</p><p>移动所选的音频与删除类似，但不是删除音频，而是复制和粘贴所选内容，就像你在文字处理器中做的那样 —— 使用标准的键盘快捷键复制或剪切，重新定位你的光标，然后粘贴。不过，为插入的内容腾出空间，需要在音频时间线上留出空位，这样你就可以录制额外的音频来填补你所创造的空白。为此，你可以使用“<ruby>选择工具<rt>Selection Tool</rt></ruby>”和“<ruby>时间偏移工具<rt>Time Shift Tool</rt></ruby>”。</p><p>要在音频中创建一个空隙，将你的“<ruby>选择工具<rt>Selection Tool</rt></ruby>”的光标放在你想添加空隙的地方。导航到“<ruby>编辑<rt>Edit</rt></ruby>”菜单，选择“<ruby>剪辑边界<rt>Clip Boundaries</rt></ruby>”子菜单，然后选择“<ruby>分割<rt>Split</rt></ruby>”。这将在你的选择点上分割你的音频。</p><p>激活顶部工具栏中的“<ruby>时间偏移工具<rt>Time Shift Tool</rt></ruby>”（图标是两个连接的箭头，分别指向左边和右边），点击并拖动分割后的音频的右半部分，创建一个间隙。</p><p><img src="https://opensource.com/sites/default/files/uploads/audacity-split.jpg" alt="空隙" title="Spacer"></p><p><strong>我的快捷方式：</strong> 我用 <code>K</code> 来分割，用 <code>T</code> 来激活“<ruby>时间偏移工具<rt>Time Shift Tool</rt></ruby>”。</p><h3 id="导出音频" tabindex="-1">导出音频 <a class="header-anchor" href="#导出音频" aria-label="Permalink to “导出音频”">​</a></h3>',11)),r("p",null,[t[19]||(t[19]=i("当你对你的音频感到满意时，你可以导出它，这样你就可以与他人分享。Audacity 可以选择它能够导出的格式，并且它能够将其输出到像 ",-1)),u(a,{href:"https://opensource.com/article/21/11/linux-line-commands-reclaim-space-converting-files#audio"},{default:l(()=>[...t[18]||(t[18]=[i("ffmpeg",-1)])]),_:1}),t[20]||(t[20]=i(" 这样的工具，以获得比你可能永远需要的更多格式。",-1))]),r("p",null,[t[22]||(t[22]=i("我更喜欢用 FLAC 格式输出音频，这种音频格式有点像 WAV，只是它是无损压缩的。它只占用一小部分空间，而没有任何质量上的损失。要尝试它，去“",-1)),t[23]||(t[23]=r("ruby",null,[i("文件"),r("rt",null,"File")],-1)),t[24]||(t[24]=i("”菜单，选择“",-1)),t[25]||(t[25]=r("ruby",null,[i("导出"),r("rt",null,"Export")],-1)),t[26]||(t[26]=i("”子菜单，然后选择“",-1)),t[27]||(t[27]=r("ruby",null,[i("导出音频"),r("rt",null,"Export Audio")],-1)),t[28]||(t[28]=i("”。有了 FLAC 文件作为你的 ",-1)),u(a,{href:"https://opensource.com/article/19/7/what-golden-image"},{default:l(()=>[...t[21]||(t[21]=[i("黄金镜像",-1)])]),_:1}),t[29]||(t[29]=i("，你可以用 SoundConverter 把你的文件转换成任何数量的传输目标的最佳格式 —— 用于浏览器的 Ogg Vorbis 或 Opus 或 Webm，用于苹果设备的 M4A 文件，也许还有用于传统系统的 MP3。",-1))]),r("p",null,[t[31]||(t[31]=i("如果你只是想从 Audacity 快速简单地导出，简单的选择是 Ogg Vorbis。这是一种开源的文件格式，可以在大多数网页浏览器（Firefox、Chromium、Chrome、Android 和 Edge）和 ",-1)),u(a,{href:"https://opensource.com/article/21/2/linux-media-players"},{default:l(()=>[...t[30]||(t[30]=[i("如 VLC、mpv 等媒体播放器",-1)])]),_:1}),t[32]||(t[32]=i(" 播放。",-1))]),t[55]||(t[55]=r("h3",{id:"探索-audacity",tabindex:"-1"},[i("探索 Audacity "),r("a",{class:"header-anchor",href:"#探索-audacity","aria-label":"Permalink to “探索 Audacity”"},"​")],-1)),r("p",null,[t[34]||(t[34]=i("Audacity 是开源软件世界中的一个经典动力工具。基本的录音和编辑仅仅是个开始。你可以添加效果、",-1)),u(a,{href:"https://opensource.com/life/14/10/how-clean-digital-recordings-using-audacity"},{default:l(()=>[...t[33]||(t[33]=[i("过滤掉（一些）噪音",-1)])]),_:1}),t[35]||(t[35]=i("、调整速度、改变音高等等。无论你是在学校录制讲座、混合鼓循环、为视频游戏拼接声音，还是只是在探索音频世界，都可以去启动 Audacity，发挥创意！",-1))]),t[56]||(t[56]=r("hr",null,null,-1)),r("p",null,[t[37]||(t[37]=i("via: ",-1)),u(a,{href:"https://opensource.com/article/21/12/audacity-linux-creative-app"},{default:l(()=>[...t[36]||(t[36]=[i("https://opensource.com/article/21/12/audacity-linux-creative-app",-1)])]),_:1})]),r("p",null,[t[42]||(t[42]=i("作者：",-1)),u(a,{href:"https://opensource.com/users/seth"},{default:l(()=>[...t[38]||(t[38]=[i("Seth Kenlon",-1)])]),_:1}),t[43]||(t[43]=i(" 选题：",-1)),u(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[39]||(t[39]=[i("lujun9972",-1)])]),_:1}),t[44]||(t[44]=i(" 译者：",-1)),u(a,{href:"https://github.com/wxy"},{default:l(()=>[...t[40]||(t[40]=[i("wxy",-1)])]),_:1}),t[45]||(t[45]=i(" 校对：",-1)),u(a,{href:"https://github.com/wxy"},{default:l(()=>[...t[41]||(t[41]=[i("wxy",-1)])]),_:1})]),r("p",null,[t[48]||(t[48]=i("本文由 ",-1)),u(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[46]||(t[46]=[i("LCTT",-1)])]),_:1}),t[49]||(t[49]=i(" 原创编译，",-1)),u(a,{href:"https://linux.cn/"},{default:l(()=>[...t[47]||(t[47]=[i("Linux中国",-1)])]),_:1}),t[50]||(t[50]=i(" 荣誉推出",-1))])])}const C=o(p,[["render",y]]);export{k as __pageData,C as default};
